/**
 * The command log: the durable source of truth.
 *
 * The engine is deterministic, so its state is a pure function of
 * (seed, ordered inputs). The log therefore stores inputs, not state:
 * - `open`: a guest account was opened;
 * - `command`: a user's place or cancel command;
 * - `ticks`: the simulated market advanced N ticks since the previous entry,
 *   between times `from` and `at`.
 *
 * Bot orders are never logged; they are regenerated by replaying the same
 * ticks with the same seed. On startup the host replays the session's log and
 * arrives at exactly the state it had before. See docs/adr/0004-command-log.md.
 */

import type { LogEntry } from "@marketlab/engine";
import { z } from "zod";

/** Defined next to the engine, which gives entries their meaning; see `SessionEngine`. */
export type { LogEntry };

const at = z.number().int().nonnegative();
/** The state hash the entry was applied to; absent on entries written before hashes were recorded. */
const h = z
  .string()
  .regex(/^[0-9a-f]{16}$/)
  .optional();
const qty = z.number().int().positive();
const money = z.number().int().positive();
const place = {
  kind: z.literal("place"),
  accountId: z.string(),
  symbol: z.string(),
  side: z.enum(["buy", "sell"]),
  qty,
};

/** Validates entries read back from storage, so a corrupt row fails loudly at startup. */
export const LogEntrySchema = z.discriminatedUnion("kind", [
  z.object({ kind: z.literal("open"), accountId: z.string(), at, h }),
  z.object({ kind: z.literal("ticks"), count: z.number().int().positive(), from: at, at, h }),
  z.object({
    kind: z.literal("command"),
    at,
    h,
    command: z.union([
      z.object({ ...place, type: z.literal("market") }),
      z.object({ ...place, type: z.literal("limit"), limitPrice: money }),
      z.object({ ...place, type: z.literal("stop"), stopPrice: money }),
      z.object({ kind: z.literal("cancel"), accountId: z.string(), orderId: z.string() }),
    ]),
  }),
]);

/** How long ended sessions are kept, for replay and inspection. */
export const RETENTION_DAYS = 7;
const RETENTION_MS = RETENTION_DAYS * 24 * 60 * 60 * 1000;

/**
 * Sessions that started before this instant are past retention at `now`:
 * plain milliseconds, so the rule cannot depend on a database time zone.
 */
export const retentionCutoff = (now: number): number => now - RETENTION_MS;

/** True if a session that started at `startedAt` is past retention at `now`. */
export const pastRetention = (startedAt: number, now: number): boolean =>
  startedAt < retentionCutoff(now);

export interface Session {
  readonly id: number;
  readonly seed: number;
  readonly startedAt: number;
  readonly entries: readonly LogEntry[];
}

/**
 * A point-in-time copy of the engine and its read models, taken right after
 * log entry `seq` was applied. It is an optimisation only: startup restores it
 * and replays the entries after `seq` instead of the whole log. The log remains
 * the source of truth, and a snapshot that fails its checks is ignored.
 */
export interface StoredSnapshot {
  readonly seq: number;
  /** `Exchange.stateHash()` at that point; checked again after restoring. */
  readonly stateHash: string;
  /** The serialised state, as JSON text. */
  readonly state: string;
}

/** Another process holds the single-writer lock: it, not this one, owns the log. */
export class LockHeldError extends Error {
  override name = "LockHeldError";
}

/** Startup waited as long as it may for another process to release the writer lock. */
export class LockWaitTimeoutError extends Error {
  override name = "LockWaitTimeoutError";
}

/** The session gained entries this process did not write while its log was suspended. */
export class LogHeadMovedError extends Error {
  override name = "LogHeadMovedError";
}

export interface CommandLog {
  readonly kind: "postgres" | "memory";
  /**
   * False while the log is suspended: it holds no connection (and no writer
   * lock). Any other call reconnects first.
   */
  readonly connected: boolean;
  /** Releases the writer lock and the connection, so the database can idle. */
  suspend(): Promise<void>;
  /**
   * Reconnects if suspended, retaking the writer lock without waiting, and
   * checks that the session still has exactly `expectedSeq` entries. Throws
   * `LockHeldError` if another process holds the lock, `LogHeadMovedError` if
   * one wrote to the session. A no-op when connected and already checked.
   */
  resume(sessionId: number, expectedSeq: number): Promise<void>;
  /**
   * Returns the current session with its entries, or starts a new one when the
   * latest session is older than `maxAgeMs`.
   */
  openSession(now: number, maxAgeMs: number, newSeed: number): Promise<Session>;
  /** Appends entry number `seq` (1-based, gap-free) to the session. */
  append(sessionId: number, seq: number, entry: LogEntry): Promise<void>;
  /** Up to `limit` entries with sequence numbers above `after`, in order. */
  readEntries(sessionId: number, after: number, limit: number): Promise<LogEntry[]>;
  /** The session's latest snapshot, if it has one. */
  loadSnapshot(sessionId: number): Promise<StoredSnapshot | null>;
  /** Stores a snapshot, replacing the session's previous one. */
  saveSnapshot(sessionId: number, snapshot: StoredSnapshot): Promise<void>;
  /**
   * Deletes sessions (with their entries and snapshots) that started more
   * than `RETENTION_DAYS` before `now`. The latest session is always kept.
   */
  pruneSessions(now: number): Promise<void>;
  close(): Promise<void>;
}

export function parseEntry(value: unknown): LogEntry {
  return LogEntrySchema.parse(value) as LogEntry;
}
